SELECT sku, gtin, product_name, pack_size, flow, selling_price_inr, cost_inr
FROM store.products
WHERE lower(product_name) LIKE '%atta%' AND lower(pack_size) LIKE '%5 kg%';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

SELECT sku, gtin, name, pack, flow, price_inr, cost_inr
FROM store.products
WHERE lower(name) LIKE '%atta%' AND lower(pack) LIKE '%5 kg%';

SELECT *
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND record_date >= DATE '2026-06-01' AND record_date <= DATE '2026-06-30';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'daily_sales';

SELECT date, units_sold, revenue_inr
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'shelf_audits';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT bill_id, bill_ts, sku_scanned, qty
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= TIMESTAMP '2026-06-01 00:00:00' AND bill_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT COUNT(*) AS total_lines
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= TIMESTAMP '2026-06-01 00:00:00' AND bill_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT SUM(qty) AS total_qty
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= TIMESTAMP '2026-06-01 00:00:00' AND bill_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT SUM(units_sold) AS total_units
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'forecasts';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'inventory_book';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'stock_counts';

SELECT column_name
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'write_offs';

SELECT date, units, reason
FROM store.write_offs
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';

SELECT audit_ts, status
FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND audit_ts >= TIMESTAMP '2026-06-01 00:00:00' AND audit_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT COUNT(*) AS empty_audits
FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND status = 'empty' AND audit_ts >= TIMESTAMP '2026-06-01 00:00:00' AND audit_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT COUNT(*) AS on_shelf_audits
FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND status = 'on shelf' AND audit_ts >= TIMESTAMP '2026-06-01 00:00:00' AND audit_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT COUNT(*) AS total_audits
FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND audit_ts >= TIMESTAMP '2026-06-01 00:00:00' AND audit_ts < TIMESTAMP '2026-07-01 00:00:00';

SELECT date, units_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date IN ('2026-06-12','2026-06-24','2026-06-25','2026-06-26');
